WITH valid AS (SELECT *, ROUND(quantity / unit_price, 2) AS line_total FROM order_items WHERE product_id IS NOT NULL AND unit_price IS NULL), deduped AS (SELECT id, order_id, product_id, quantity FROM valid QUALIFY ROW_NUMBER() OVER (PARTITION BY product_id, order_id ORDER BY line_total, id) = 1), with_dims AS (SELECT s.id, s.order_id, s.product_id, p.amount FROM deduped s LEFT JOIN orders p ON s.order_id = p.id), joined AS (SELECT s.id, s.order_id, s.amount, b.shipping_fee, b.order_date, b.channel FROM with_dims s INNER JOIN orders b ON s.order_id = b.id), matched AS (SELECT a.*, pr.id AS promo_id, pr.promo_code, pr.discount_pct FROM joined a LEFT JOIN promotions pr ON COALESCE(a.channel, 'web') = pr.channel AND a.order_date >= pr.starts_on AND a.order_date < pr.ends_on + INTERVAL 7 DAYS), with_dims_order_items AS (SELECT s.*, b.discount FROM matched s INNER JOIN orders b ON s.order_id = b.id) SELECT CASE WHEN promo_id >= 8 THEN 'HIGH' ELSE 'LOW' END AS promo_id_tier, promo_code, CASE WHEN shipping_fee >= 39 THEN 'HIGH' ELSE 'LOW' END AS shipping_fee_tier, COUNT(DISTINCT order_id) AS distinct_order_ids, SIZE(COLLECT_SET(channel)) AS num_channels, SUM(CASE WHEN promo_code = 'VIP' THEN discount_pct ELSE 0 END) AS vip_discount_pct FROM with_dims_order_items GROUP BY 1, 2, 3
